package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.ByteOrder;
import java.util.*;
import org.apache.commons.compress.utils.BitInputStream;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen1Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming a reasonable value for testing











    @Test
    public void testReadBits_LittleEndian_OverflowLogic() throws IOException {
        // Testing the logic where bitsCachedSize >= 57 and we need more bits
        // We need to trigger: if (bitsCachedSize < count)
        // We simulate by providing bytes and requesting a large count
        // To hit the "overflow" branch, we need count > bitsCachedSize

        // Data: 0x01, 0x02
        // Little Endian: bitsCached becomes 0x0201
        byte[] data = {0x01, 0x02};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Request 12 bits. 
        // bitsCachedSize starts 0. 
        // While loop reads 0x01 (size 8), then 0x02 (size 16).
        // Here count(12) < bitsCachedSize(16), so it skips the overflow block and goes to direct read.
        assertEquals(0x021L, bis.readBits(12)); 
    }










}

