import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen1Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming a reasonable value for testing













    @Test
    public void testReadBits_BigEndian_OverflowLogic() throws IOException {
        byte[] data = {0x01, 0x02};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);
        // Big Endian: 0x0102. Read 12 bits.
        // bitsCachedSize becomes 16. count is 12.
        // bitsOut = (0x0102 >> (16-12)) & MASKS[12] = (0x0102 >> 4) & 0xFFF = 0x010
        assertEquals(0x10L, bis.readBits(12));
    }








}

